import java.io.*;
import java.util.*;
public class Wyciek {
    public static void main(String[] a) throws Exception {
        List<InputStream> lista = new ArrayList<>();
        for (int i = 0; i < 200; i++) {
            lista.add(new FileInputStream("/etc/hostname"));
            Thread.sleep(50);
        }
        Thread.sleep(60000);
    }
}
